    'about.hero.eyebrow': 'À Propos',
    'about.hero.title': 'Votre Santé, Réinventée',
    'about.hero.subtitle': 'Des conseils nutritionnels et sportifs fondés sur des preuves, personnalisés selon votre corps, votre état et votre culture.',
    'about.mission.title': 'Notre Mission',
    'about.mission.p1': 'Gérer une maladie chronique ne devrait pas être compliqué. Nous croyons qu\'un accompagnement clair et fiable est la base d\'une santé durable.',
    'about.mission.p2': 'HealthCalc réunit la nutrition et la science de l\'exercice de niveau médical au même endroit — personnalisées selon vos analyses, vos objectifs et la cuisine que vous aimez vraiment.',
    'about.mission.p3': 'Ni régimes à la mode, ni suppositions. Seulement des étapes fondées sur des preuves, à appliquer dès aujourd\'hui.',
    'about.different.title': 'Ce Qui Nous Rend Différents',
    'about.different.card1.title': 'Basé sur des Preuves',
    'about.different.card1.desc': 'Élaboré selon les directives de l\'OMS, de l\'ADA, du NHS et de la Mayo Clinic.',
    'about.different.card2.title': 'Adapté à la Culture',
    'about.different.card2.desc': 'Des plans sains issus de plus de 52 cuisines — égyptienne, tunisienne, saoudienne, marocaine et bien plus.',
