    // About page
    'about.hero.eyebrow': 'Acerca de Nosotros',
    'about.hero.title': 'Tu Salud, Reimaginada',
    'about.hero.subtitle': 'Orientación nutricional y de fitness basada en evidencia, personalizada según tu cuerpo, tu condición y tu cultura.',
    'about.mission.title': 'Nuestra Misión',
    'about.mission.p1': 'Gestionar una enfermedad crónica no debería ser complicado. Creemos que una guía clara y confiable es la base de una salud duradera.',
    'about.mission.p2': 'HealthCalc une la nutrición y la ciencia del ejercicio de nivel médico en un solo lugar — personalizadas según tus análisis, tus objetivos y la comida que de verdad amas.',
    'about.mission.p3': 'Sin modas. Sin conjeturas. Solo pasos basados en evidencia que puedes dar hoy.',
    'about.different.title': 'Qué Nos Hace Diferentes',
    'about.different.card1.title': 'Basado en Evidencia',
    'about.different.card1.desc': 'Construido según las guías de la OMS, ADA, NHS y Mayo Clinic.',
    'about.different.card2.title': 'Adaptado Culturalmente',
    'about.different.card2.desc': 'Planes saludables de más de 52 cocinas — egipcia, tunecina, saudí, marroquí y más.',
    'about.different.card3.title': 'Informado por tus Análisis',
    'about.different.card3.desc': 'Tus resultados de laboratorio guían cada recomendación.',
    'about.different.card4.title': 'Basado en Datos',
    'about.different.card4.desc': 'Sigue tu progreso real con números reales, nunca con suposiciones.',
