    'advanced.faq.a1': 'Sie erhalten 7 Tage lang vollen Zugang ohne Kosten. Danach beginnt Ihr Abonnement automatisch, sofern Sie nicht kündigen.',
    'advanced.faq.q2': 'Kann ich jederzeit kündigen?',
    'advanced.faq.a2': 'Ja. Kündigen Sie mit wenigen Klicks in Ihrem Konto und behalten Sie den Zugriff bis zum Ende Ihres Abrechnungszeitraums.',
    'advanced.faq.q3': 'Sind meine Daten sicher?',
    'advanced.faq.a3': 'Absolut. Ihre Gesundheitsdaten sind verschlüsselt, werden nie verkauft und nur zur Erstellung Ihres Plans verwendet.',
    'advanced.faq.q4': 'Werden mehrere Erkrankungen unterstützt?',
    'advanced.faq.a4': 'Ja. Sie können mehrere Erkrankungen auswählen und wir kombinieren sie zu einem maßgeschneiderten Plan.',
    'advanced.faq.q5': 'Auf welchen Leitlinien basiert der Plan?',
    'advanced.faq.a5': 'Unsere Pläne basieren auf den veröffentlichten Leitlinien von WHO, ADA, NHS und der Mayo Clinic. Sie sind rein informativ und ersetzen keine professionelle medizinische Beratung.',
    'advanced.finalCta.cta': '7-Tage-Kostenlostest starten →',
