    fcAccFormulaBody: 'BMI = Gewicht(kg) / Größe(m)². Gesunder Bereich laut WHO 18,5–24,9. Idealgewicht über Robinson (1983) & Devine (1974) gemittelt. RMR über die Mifflin-St-Jeor-Gleichung, validiert mit indirekter Kalorimetrie.',
