    // About page
    'about.hero.eyebrow': 'Über Uns',
    'about.hero.title': 'Deine Gesundheit, neu gedacht',
    'about.hero.subtitle': 'Evidenzbasierte Ernährungs- und Fitnessberatung, abgestimmt auf deinen Körper, deine Erkrankung und deine Kultur.',
    'about.mission.title': 'Unsere Mission',
    'about.mission.p1': 'Mit einer chronischen Erkrankung zu leben sollte nicht kompliziert sein. Wir glauben, dass klare, vertrauenswürdige Begleitung das Fundament für dauerhafte Gesundheit ist.',
    'about.mission.p2': 'HealthCalc vereint Ernährung und Sportwissenschaft auf medizinischem Niveau an einem Ort — personalisiert nach deinen Laborwerten, deinen Zielen und dem Essen, das du wirklich liebst.',
    'about.mission.p3': 'Keine Moden. Kein Rätselraten. Nur evidenzbasierte Schritte, die du noch heute umsetzen kannst.',
    'about.different.title': 'Was Uns Auszeichnet',
    'about.different.card1.title': 'Evidenzbasiert',
    'about.different.card1.desc': 'Basierend auf den Leitlinien von WHO, ADA, NHS und Mayo Clinic.',
    'about.different.card2.title': 'Kulturell Angepasst',
    'about.different.card2.desc': 'Gesunde Pläne aus über 52 Küchen — ägyptisch, tunesisch, saudisch, marokkanisch und mehr.',
    'about.different.card3.title': 'Laborgestützt',
    'about.different.card3.desc': 'Deine Blutwerte leiten jede Empfehlung, die wir geben.',
    'about.different.card4.title': 'Datengesteuert',
    'about.different.card4.desc': 'Verfolge echten Fortschritt mit echten Zahlen — niemals geraten.',
    'about.approach.title': 'Unser Ansatz',
    'about.approach.step1.title': 'Bewerten',
    'about.approach.step1.desc': 'Erzähl uns von deinem Gesundheitsprofil und deinen letzten Laborergebnissen.',
    'about.approach.step2.title': 'Personalisieren',
    'about.approach.step2.desc': 'Erhalte einen Plan, der auf deine Erkrankung, Ziele und Lieblingsküche zugeschnitten ist.',
    'about.approach.step3.title': 'Verfolgen',
    'about.approach.step3.desc': 'Dokumentiere Fortschritte und passe den Plan an, wenn sich dein Körper verändert.',
    'about.team.title': 'Das Team',
    'about.team.desc': 'Entwickelt von Ernährungswissenschaftlern, Fitnessexperten und Digital-Health-Spezialisten, denen die Details wichtig sind.',
    'about.disclaimer': 'HealthCalc bietet ausschließlich Bildungsinformationen und ersetzt keine professionelle medizinische Beratung, Diagnose oder Behandlung. Konsultiere vor jedem Ernährungs- oder Trainingsprogramm immer deinen Arzt.',
    'about.cta.title': 'Bereit zu starten?',
    'about.cta.button': 'Entdecke dein Gesundheits-Universum',
